<script setup>
import {ref,computed} from 'vue'
import {Check,Clock3,MessageCircle,Users,Copy,ShieldAlert} from 'lucide-vue-next'
import {api,labels,date,features} from '../api'
import {timelineTime} from '../boarding-schedule'
const props=defineProps({row:Object,manage:String});const emit=defineEmits(['refresh','notice','manage-time'])
const peerContact=computed(()=>props.row.contacts?.[props.row.side==='owner'?'applicant':'publisher'])
const selfContact=computed(()=>props.row.contacts?.[props.row.side==='owner'?'publisher':'applicant'])
const peerRole=computed(()=>props.row.card_type==='boss'?(props.row.side==='owner'?'打手':'老板'):(props.row.side==='owner'?'老板':'打手'))
const busy=ref(false),error=ref(''),review=ref(false),tags=ref([]),body=ref(''),confirm=ref('')
async function action(path){if(busy.value)return;busy.value=true;error.value='';try{await api(path,{method:'POST',manage:props.manage});emit('refresh');confirm.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
async function sendReview(){busy.value=true;error.value='';try{await api('/reviews?match_id='+props.row.match.id,{method:'POST',data:{tags:tags.value,body:body.value},manage:props.manage});emit('notice','评价已提交，审核通过后展示');review.value=false;emit('refresh')}catch(e){error.value=e.message}finally{busy.value=false}}
async function copy(text){try{await navigator.clipboard.writeText(text);emit('notice','微信号已复制')}catch{emit('notice','请长按选中微信号复制')}}
</script>
<template><div class="application-panel stack"><div class="selected-card"><span class="tag">{{row.card_type==='boss'&&row.status==='accepted'?(row.side==='owner'?'已被打手认领':'我的认领'):row.side==='owner'?'收到的申请':'我的申请'}} #{{row.id}}</span><h3>{{row.card.map_name}} · {{row.game_id}} <span v-if="row.level">Lv.{{row.level}}</span></h3><p>{{date(row.created_at)}} {{row.source==='screenshot'?'截图录入':'提交'}}</p><p v-if="row.source==='screenshot'" class="hint">此老板由打手现场录入，无网站申请和已授权微信。</p></div><div class="progress-steps"><span class="done"><Check :size="15"/> {{row.card_type==='boss'&&row.status==='accepted'?'已认领':'已申请'}}</span><i></i><span :class="{done:row.status==='accepted'}">{{row.card_type==='boss'&&row.status==='accepted'?'微信已开放':row.status==='pending'?'等待同意':labels[row.status]}}</span><i></i><span :class="{done:row.match?.boarded_at||['boarded','completed','disputed'].includes(row.match?.status)}">{{row.match?labels[row.match.status]:'待联系'}}</span></div><p v-if="!row.match&&row.requested_start_at" class="hint">申请时段：{{timelineTime(row.requested_start_at)}} 开始 · {{row.duration_hours}} 小时（北京时间）</p><p v-if="row.notes" class="note">{{row.notes}}</p><p v-if="row.status==='pending'" class="hint">{{date(row.expires_at)}} 到期；接受申请仅表示愿意联系，尚未占用老板位。</p><div v-if="row.offered_team" class="selected-card"><small>认领打手的队伍</small><strong>{{row.offered_team.map_name}} · {{row.offered_team.game_id}} · 余 {{row.offered_team.remaining}} 位</strong></div><div v-if="row.status==='pending'" class="button-row"><template v-if="row.side==='owner'"><button class="button primary" :disabled="busy" @click="action('/applications/'+row.id+'/accept')">同意并交换微信</button><button class="button" :disabled="busy" @click="action('/applications/'+row.id+'/reject')">拒绝申请</button></template><button v-else class="button" :disabled="busy" @click="action('/applications/'+row.id+'/cancel')">撤回申请</button></div><template v-if="row.contacts"><div class="section-label"><MessageCircle :size="17"/> 联系{{peerRole}}</div><div class="contact-card"><small>{{peerRole}}微信 · 已向你开放</small><template v-if="peerContact"><strong v-if="peerContact.wechat">{{peerContact.wechat}}<button class="button small" @click="copy(peerContact.wechat)"><Copy :size="14"/>复制微信号</button></strong><img v-if="peerContact.qr" :src="peerContact.qr" class="qr-preview" :alt="peerRole+'微信二维码'"></template><p v-else class="hint">联系方式已删除或到期，请通过已建立的微信联系沟通。</p></div><details v-if="selfContact" class="form-more"><summary>我向对方提供的微信</summary><p>{{selfContact.wechat||'已提供微信二维码'}}</p><img v-if="selfContact.qr" :src="selfContact.qr" class="qr-preview" alt="我的微信二维码"></details></template><template v-if="row.match"><p class="hint" v-if="row.match.status==='contacted'">{{row.card_type==='boss'?'认领已成功，无需老板同意。':''}}微信沟通安排后，由打手确认上车，系统才会占用老板位。</p><button v-if="['contacted','boarded','disputed'].includes(row.match.status)&&row.match.can_board" class="button full" @click="emit('manage-time')">调整老板上车 / 结束时间</button><button v-if="row.match.status==='contacted'&&row.match.can_board" class="button primary full" :disabled="busy" @click="action('/matches/'+row.match.id+'/board')"><Users :size="17"/> 确认上车并占位</button><div v-if="row.match.planned_start_at" class="application-schedule"><strong>约定挂机时段</strong><p>{{timelineTime(row.match.planned_start_at)}} — {{timelineTime(row.match.expected_end_at)}}<small>北京时间</small></p><small v-if="row.match.boarded_at">实际确认上车：{{timelineTime(row.match.boarded_at)}}</small><small v-if="row.match.finished_at">实际结束：{{timelineTime(row.match.finished_at)}}</small></div><template v-if="row.match.status==='boarded'"><button v-if="row.match.can_complete" class="button primary full" :disabled="busy" @click="confirm='complete'">结束本次挂机并释放老板位</button><p v-else class="hint">你已上车，可以离开页面。挂机结束由打手处理，无需你再次确认；之后可通过原管理链接查看结果。</p></template><p v-if="row.match.status==='completed'" class="hint">本次挂机已结束，老板无需再确认。</p><details v-if="['contacted','boarded','disputed'].includes(row.match.status)" class="form-more"><summary>遇到问题 / 取消组队</summary><div class="button-row"><button v-if="row.match.status==='boarded'" class="text-button" @click="confirm='dispute'">标记争议</button><button class="button danger-outline" @click="confirm='cancel'">取消组队{{row.match.status!=='contacted'?'并释放老板位':''}}</button></div></details><div v-if="confirm" class="confirm-box"><p>{{confirm==='complete'?'结束本次挂机并释放老板位？老板无需再次确认。':confirm==='cancel'?'确认取消本次组队？已占用的老板位会释放，请先与对方沟通。':'确认标记争议？老板位暂时保留，可由任一方取消或由管理员处理。'}}</p><div class="button-row"><button class="button primary" :disabled="busy" @click="action('/matches/'+row.match.id+'/'+confirm)">确认</button><button class="button" @click="confirm=''">返回</button></div></div><button v-if="row.source!=='screenshot'&&row.match.status==='completed'&&!row.match.reviewed" class="button primary full" @click="review=!review">评价这次组队（选填）</button><p v-if="row.match.reviewed" class="hint">你的评价已提交，每次撮合每方只能评价一次。</p><form v-if="review" @submit.prevent="sendReview" class="stack"><div class="tag-options"><label v-for="tag in (features.teammate_recruitment?['刷怪稳定','BUFF 稳定','多次断花','沟通守时']:['刷怪稳定','沟通守时'])"><input type="checkbox" :value="tag" v-model="tags">{{tag}}</label></div><textarea v-model="body" maxlength="500" placeholder="补充真实体验，不要填写个人隐私。"></textarea><button class="button primary" :disabled="busy||!tags.length">提交审核</button></form></template><p v-if="error" class="error" role="alert">{{error}}</p></div></template>
